-- Reruns update GeoArea, fill missing/blank Email and Address, and insert missing demo entries.
-- Emails use example.com; addresses are explicitly fictitious. Existing nonblank contacts are preserved.
-- ContactPhone uses 0 on insert because it is NOT NULL.

BEGIN;
SET LOCAL client_encoding = 'UTF8';
LOCK TABLE responsible_entities IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE seed_portuguese_districts (
    name text PRIMARY KEY,
    geo_area geometry(MultiPolygon,4326) NOT NULL,
    CHECK (NOT ST_IsEmpty(geo_area) AND ST_IsValid(geo_area))
) ON COMMIT DROP;

