WITH districts AS (
    SELECT name, geo_area FROM seed_portuguese_districts
), entity_types (type, label) AS (
    VALUES
        ('BOMBEIROS', 'Bombeiros'),
        ('PROTECAO_CIVIL', 'Proteção Civil'),
        ('POLICIA', 'Polícia'),
        ('CAMARA_MUNICIPAL', 'Câmara Municipal'),
        ('SERVICOS_ANIMAL_AMBIENTAL', 'Serviços Animal e Ambiental'),
        ('INEM', 'INEM')
), entries AS (
    SELECT '[DEMO] ' || t.label || ' - ' || d.name AS name, t.type, d.geo_area,
           lower(t.type) || '.' ||
               replace(translate(lower(d.name), 'áàâãéêíóôõúç', 'aaaaeeiooouc'), ' ', '-') ||
               '@example.com' AS email,
           '[FICTÍCIA] Rua de Demonstração, 1 - ' || d.name || ', Portugal' AS address
    FROM districts AS d
    CROSS JOIN entity_types AS t
), updated AS (
    UPDATE responsible_entities AS existing
    SET "GeoArea" = e.geo_area,
        "Email" = COALESCE(NULLIF(btrim(existing."Email"), ''), e.email),
        "Address" = COALESCE(NULLIF(btrim(existing."Address"), ''), e.address)
    FROM entries AS e
    WHERE existing."Name" = e.name AND existing."Type" = e.type
      AND (existing."GeoArea" IS DISTINCT FROM e.geo_area
           OR NULLIF(btrim(existing."Email"), '') IS NULL
           OR NULLIF(btrim(existing."Address"), '') IS NULL)
    RETURNING existing."Id"
), inserted AS (
    INSERT INTO responsible_entities
        ("Name", "Email", "Address", "ContactPhone", "Type", "GeoArea")
    SELECT e.name, e.email, e.address, 0, e.type, e.geo_area
    FROM entries AS e
    WHERE NOT EXISTS (
        SELECT 1
        FROM responsible_entities AS existing
        WHERE existing."Name" = e.name AND existing."Type" = e.type
    )
    RETURNING "Id"
)
SELECT (SELECT COUNT(*) FROM inserted) AS inserted_count,
       (SELECT COUNT(*) FROM updated) AS updated_count;

COMMIT;
